 if(action==='add-card'&&value==='photo'){materialPicker('free');return}
 if(action==='photo-adjust'&&draft?.templateId==='portrait'){depthTab='photo';go('customize');return}
 if(action==='save'&&draft?.templateId==='portrait'){if(!draft.state.cards[0].elements.some(e=>e.kind==='image')){say('先从素材库选择一张照片');return}const isNew=!db.works.some(w=>w.id===draft.id);if(isNew){save(true);if(!draft)clearRecovery();return}}
