const baseUpdate=updatePreview;updatePreview=function(){baseUpdate();paintDepth()};
function photoPoints(stage){const rect=stage.getBoundingClientRect();return [...pointers.entries()].map(([id,p])=>({id,x:(p.x-rect.x)*300/rect.width,y:(p.y-rect.y)*300/rect.width}))}
app.addEventListener('pointerdown',e=>{const stage=e.target.closest('#depth-stage'),compare=e.target.closest('#compare-depth');if(compare){e.preventDefault();compare.setPointerCapture(e.pointerId);showCompare=true;paintDepth();return}if(!stage||e.button>0)return;e.preventDefault();stage.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(!depthGesture)depthGesture={snapshot:S.clone(draft),changed:false,clock:!!e.target.closest('#clock-hit'),startX:e.clientX,startY:e.clientY};if(depthGesture.clock){depthTab='clock';$('#clock-hit').classList.add('active')}else{photoCamera.update(photoPoints(stage),draft.state.cards[0].template,cameraModel.photoControlRegion(draft.state.cards[0]))}});
app.addEventListener('pointermove',e=>{if(!depthGesture||!pointers.has(e.pointerId))return;const stage=$('#depth-stage');if(!stage)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const c=draft.state.cards[0];if(depthGesture.clock){const point=photoPoints(stage)[0],height=300/draft.state.canvasAspect;let best='',dist=Infinity;for(const p of cameraModel.PHOTO_CLOCK_POSITIONS){const box=cameraModel.photoClockLayout(300,height,p),d=Math.hypot(point.x-box.x-box.w/2,point.y-box.y-box.h/2);if(d<dist){dist=d;best=p}}c.template.clockPosition=best;c.template.clockAuto=false;}else Object.assign(c.template,photoCamera.update(photoPoints(stage),c.template,cameraModel.photoControlRegion(c)));if(Math.hypot(e.clientX-depthGesture.startX,e.clientY-depthGesture.startY)>2)depthGesture.changed=true;requestDepthPaint()});
function endDepthPointer(e){if(showCompare){showCompare=false;paintDepth()}if(!pointers.has(e.pointerId))return;pointers.delete(e.pointerId);const stage=$('#depth-stage');if(pointers.size){photoCamera.update(photoPoints(stage),draft.state.cards[0].template,cameraModel.photoControlRegion(draft.state.cards[0]));return}if(depthGesture?.changed){undo.push(depthGesture.snapshot);redo=[]}const clock=depthGesture?.clock;depthGesture=null;photoCamera.reset();if(clock){faceFocus='time';render()}else paintDepth()}
app.addEventListener('pointerup',endDepthPointer);app.addEventListener('pointercancel',endDepthPointer);window.addEventListener('blur',()=>{showCompare=false;pointers.clear();depthGesture=null;photoCamera.reset();paintDepth()});
let wheelTimer;app.addEventListener('wheel',e=>{if(!e.target.closest('#depth-stage')||!draft)return;e.preventDefault();if(!wheelTimer)history();const t=draft.state.cards[0].template;t.zoom=Math.max(.25,Math.min(3,t.zoom*Math.exp(-e.deltaY*.0015)));requestDepthPaint();clearTimeout(wheelTimer);wheelTimer=setTimeout(()=>{wheelTimer=null},200)},{passive:false});
document.addEventListener('keydown',e=>{if(e.target.id==='compare-depth'&&(e.key===' '||e.key==='Enter')){e.preventDefault();showCompare=true;paintDepth()}if(e.target.matches('.file-button')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.querySelector('input').click()}});document.addEventListener('keyup',e=>{if(e.target.id==='compare-depth'){showCompare=false;paintDepth()}});
