document.addEventListener('change',e=>{if(e.target.id==='collection-filter'){materialGroup=e.target.value;render()}if(e.target.id==='material-sort'){materialSort=e.target.value;render()}if(e.target.id==='asset-import')importFiles(e.target.files,pendingImportType);if(e.target.id==='asset-pair')importFiles(e.target.files,'cutout',pairTarget)});
