function facePages(){if(boardSession&&draft.templateId?.startsWith('mix-'))return [['color','颜色'],...(editableSources().length||draft.templateId==='mix-memory'?[['content','内容']]:[])];if(draft.kind==='piece')return [['style','外观'],['color','颜色'],...(draft.state.cards[0].elements.length||editableSources().length?[['content','内容']]:[])];return [['style','外观'],['color',draft.templateId==='portrait'?'背景':'颜色'],...(draft.templateId==='portrait'||editableSources().length||draft.templateId==='mix-memory'?[['content','内容']]:[])]}
