 if(id==='portrait'){html=`<button class="face-hit" data-action="face-focus" data-value="time" style="${clockHitStyle()}" aria-label="编辑时间"><span>时间</span></button><button class="face-hit photo-hit" data-action="face-focus" data-value="photo" style="left:14%;top:46%;width:72%;height:47%" aria-label="编辑照片"><span>照片</span></button>`}
 else if(id.startsWith('album'))html='<button class="face-hit" data-action="pick-album" style="inset:9% 9% 24%" aria-label="更换专辑封面"><span>专辑</span></button><button class="face-hit" data-action="face-text" data-value="album" data-match="album" aria-label="编辑专辑文字"><span>文字</span></button>';
 else if(id==='anniversary-photo')html='<button class="face-hit" data-action="pick-library" data-image="photo" style="left:4%;top:4%;width:92%;height:62%" aria-label="更换纪念日照片"><span>照片</span></button><button class="face-hit" data-action="face-text" data-value="anniversary" data-match="anniversary" style="left:4%;top:74%;width:92%;height:20%" aria-label="编辑纪念日"><span>纪念日</span></button>';
