 if(faceFocus==='photo')return `<div class="face-crop-tools"><button class="face-pill" data-action="pick-library">${icon('photo')}更换照片</button>${t.photoMode==='photo'?'<button class="face-pill" data-action="fill-photo">重置构图</button>':'<button class="face-pill" data-action="fit-photo">完整显示</button><button class="face-pill" data-action="fill-photo">铺满</button>'}</div><div class="face-zoom"><button data-action="zoom-step" data-value="-0.1" aria-label="缩小照片">−</button><input type="range" min="${t.photoMode==='photo'?1:.25}" max="3" step=".01" value="${t.zoom}" data-field="depth-zoom" aria-label="照片缩放"><output id="zoom-output">${Math.round(t.zoom*100)}%</output><button data-action="zoom-step" data-value="0.1" aria-label="放大照片">＋</button></div>`;
