function focusedEditor(){prepareFace();return `<main class="face-editor ${faceFocus?'is-focused':''}" aria-label="${boardSession?'贴纸编辑器':'模板编辑器'}"><header class="face-header"><button class="face-round" data-action="${faceFocus?'face-unfocus':'back'}" aria-label="${faceFocus?'返回编辑项':boardSession?'取消贴纸修改':'返回作品'}">${icon('back')}</button>${boardSession?`<span class="face-name">${esc(cardLabel(draft.state.cards[0]))}</span>`:`<button class="face-name" data-action="rename-draft">${esc(draft.name)}</button>`}<button class="face-done" data-action="face-done">完成</button></header><nav class="face-pages" aria-label="编辑项目">${faceFocus?`<span class="focus-heading">${faceTitle()}</span>`:facePages().map(([id,name])=>`<button data-action="face-page" data-value="${id}" aria-current="${facePage===id?'page':'false'}" class="${facePage===id?'active':''}">${name}</button>`).join('')}</nav><section class="face-stage-zone" id="face-swipe-zone" aria-label="作品预览，左右滑动切换编辑项"><div class="face-utility"><button class="face-round" data-action="undo" aria-label="撤销" ${undo.length?'':'disabled'}>${icon('undo')}</button><button class="face-round" data-action="redo" aria-label="重做" ${redo.length?'':'disabled'}>${icon('redo')}</button></div>${draft.templateId==='portrait'?`<button class="face-compare" id="compare-depth" aria-label="按住对比景深">${icon('compare')}</button>`:''}${faceArt()}${!faceFocus?`<button class="face-side prev" data-action="face-step" data-value="-1" aria-label="上一编辑项">${icon('back')}</button><button class="face-side next" data-action="face-step" data-value="1" aria-label="下一编辑项">${icon('arrow')}</button>`:''}</section><section class="face-controls" aria-label="${faceTitle()}选项">${faceControls()}</section><footer class="face-footer">${faceFocus?`<span class="face-gesture-note">${faceFocus==='time'?'拖动时间，靠近边缘自动对齐':'拖动照片 · 双指或滚轮缩放'}</span>`:faceDots()}<button class="face-round face-more" data-action="face-more" aria-label="更多编辑选项">•••</button></footer></main>`}
