function mountFaceHotspots(){const parent=$('.face-art');if(!parent||!draft)return;const pr=parent.getBoundingClientRect(),cap=draft.state.cards[0].capability||{};for(const hit of parent.querySelectorAll('[data-match]')){const values=hit.dataset.match==='course'?[cap.courses?.[Number(hit.dataset.index)||0]?.name,cap.courses?.[Number(hit.dataset.index)||0]?.room]:[cap.title,cap.artist];const texts=[...parent.querySelectorAll('svg text')],nodes=hit.dataset.match==='anniversary'?texts:values.filter(Boolean).map(v=>texts.find(n=>n.textContent.trim()===v)).filter(Boolean);if(!nodes.length){hit.style.cssText='left:7%;right:7%;bottom:7%;height:30%';continue}const boxes=nodes.map(n=>n.getBoundingClientRect());const x=Math.min(...boxes.map(b=>b.left))-pr.left-8,y=Math.min(...boxes.map(b=>b.top))-pr.top-8,r=Math.max(...boxes.map(b=>b.right))-pr.left+8,b=Math.max(...boxes.map(b=>b.bottom))-pr.top+8;hit.style.cssText=`left:${Math.max(2,x)/pr.width*100}%;top:${Math.max(2,y)/pr.height*100}%;width:${Math.min(pr.width-4,r-x)/pr.width*100}%;height:${Math.max(42,b-y)/pr.height*100}%`}}
